import b200probe as bp
lib=ctypes.CDLL('/tmp/w/libw.so')
torch.manual_seed(2)
dev='cuda'
W=torch.randn(18432,3072,device=dev)/(3072**0.5)
bias=torch.randn(18432,device=dev)
sms=torch.cuda.get_device_properties(0).multi_processor_count
def caller(tile):
    def fn(emb,Wt,bs,*outs):
        arr=(ctypes.c_void_p*6)(*[o.data_ptr() for o in outs])
        st=ctypes.c_void_p(torch.cuda.current_stream().cuda_stream)
        a=[ctypes.c_void_p(emb.data_ptr()),ctypes.c_void_p(Wt.data_ptr()),ctypes.c_void_p(bs.data_ptr()),arr,ctypes.c_int(emb.shape[0])]
        if tile=='stream': r=lib.adamod_stream(*a,st)
        else: r=getattr(lib,'adamod_gemm_'+tile)(*a,ctypes.c_int(0),ctypes.c_int(sms),st)
        assert r==0,("status",tile,r)
    return fn
def err(emb,outs):
    ref=(emb.double()@W.double().t()+bias.double()); m=0
    for c in range(6): m=max(m,(outs[c].double()-ref[:,c*3072:(c+1)*3072]).abs().max().item())
    return m
def run(Bs,tiles,rounds=3):
    for B in Bs:
        emb=torch.randn(B,3072,device=dev); outs=[torch.zeros(B,3072,device=dev) for _ in range(6)]
        res={t:[] for t in tiles}; errs={}
        for t in tiles:
